body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

h1 { font-size: 26px; }

h2 {
  font-size: 15px;
  font-family: ui-monospace, "Cascadia Mono", monospace;
  margin: 0 0 8px;
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.call {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
  margin-bottom: 12px;
  border-left: 4px solid #e4e4e7;
}

.call.ok { border-left-color: #0a7a35; }
.call.bad { border-left-color: #b91c1c; }

.status {
  display: inline-block;
  min-width: 40px;
  text-align: center;
  border-radius: 999px;
  padding: 1px 8px;
  font-size: 13px;
  font-weight: 700;
  color: #ffffff;
  background-color: #71717a;
}

.s-2xx { background-color: #0a7a35; }
.s-4xx { background-color: #b45309; }
.s-5xx { background-color: #b91c1c; }
.s-err { background-color: #b91c1c; }

pre {
  background-color: #f4f4f5;
  border-radius: 8px;
  padding: 10px 12px;
  margin: 0 0 8px;
  overflow-x: auto;
  font-size: 13px;
  white-space: pre-wrap;
}

pre:last-child { margin-bottom: 0; }

// Deploy token-ыг КОД дотор биш, орчны нууцаас (env) унших ёстой.
// env.DEPLOY_TOKEN байхгүй бол алдаа шид.
// Лог/хариунд token-ыг ЗАДГАЙГААР бүү гарга — сүүлийн 4 оронг л үлдээж далда.

function deploy(env) {
