}

// «Deploy турших самбар». Энэ файлыг өөрчлөх шаардлагагүй.
const output = document.getElementById("output");
function panel(cls, testid, title, lines) {
  const box = document.createElement("section");
  box.className = "call " + cls;
  box.dataset.testid = testid;
  const h = document.createElement("h2");
  h.textContent = title;
  box.append(h);
  for (const line of lines) {
    const p = document.createElement("pre");
    p.textContent = line;
    box.append(p);
  }
  output.append(box);
  return box;
}

window.DEPLOY_OK = null;
window.DEPLOY_ERROR = null;
window.DEPLOY_BOOT_ERROR = null;

try {
  window.DEPLOY_OK = deploy({ DEPLOY_TOKEN: "ghp_live_SECRET_ABCD1234" });
  panel("ok", "ok", "Нууц утгатай deploy", [JSON.stringify(window.DEPLOY_OK, null, 2)]);
} catch (problem) {
  window.DEPLOY_BOOT_ERROR = problem.message;
  panel("bad", "boot", "deploy алдаа", [problem.message]);
}

try {
  deploy({});
  panel("bad", "missed", "Дутуу нууц илрээгүй", ["deploy нь дутуу DEPLOY_TOKEN-ыг анзаарсангүй"]);
} catch (problem) {
  window.DEPLOY_ERROR = problem.message;
  panel("ok", "err", "Дутуу нууц зөв илэрлээ", [problem.message]);
}

document.body.dataset.ready = "1";

