// Deploy token-ыг орчны нууцаас уншиж, далдалж ашиглана.

function deploy(env) {
  const token = env.DEPLOY_TOKEN;
  if (!token) {
    throw new Error("DEPLOY_TOKEN тохируулаагүй байна");
  }
  const masked = "\u2022\u2022\u2022\u2022" + token.slice(-4);
  return { deployed: true, target: "production", token: masked };
}
